alter table public.crm_experiments add column if not exists sequential_alpha numeric not null default 0.05 check(sequential_alpha>0 and sequential_alpha<1);
alter table public.crm_experiments add column if not exists max_sequential_looks integer not null default 10 check(max_sequential_looks between 1 and 1000);
create or replace function public.crm_experiment_report(p_experiment_id uuid) returns jsonb language plpgsql stable security invoker set search_path=public as $$
declare v_user uuid:=auth.uid(); v_alpha numeric; v_looks int; v_min int; v_reg numeric; v_base_id uuid; v_base_n int; v_look int; v_alpha_look numeric; v_z numeric; v jsonb;
begin
 if v_user is null then raise exception 'UNAUTHORIZED'; end if;
 select sequential_alpha,max_sequential_looks into v_alpha,v_looks from public.crm_experiments where id=p_experiment_id and user_id=v_user;
 if not found then raise exception 'experiment_not_found'; end if;
 select coalesce(max(min_sample_size),100),coalesce(max(max_regression),0) into v_min,v_reg from public.crm_experiment_guardrails where experiment_id=p_experiment_id and enabled and metric_name in ('conversion','conversion_rate');
 select id into v_base_id from public.crm_experiment_variants where experiment_id=p_experiment_id order by case when lower(name) in ('control','baseline','a') then 0 else 1 end,name limit 1;
 select count(distinct x.subject_key)::int into v_base_n from public.crm_experiment_exposures x where x.variant_id=v_base_id;
 v_look:=least(v_looks,greatest(1,ceil(greatest(coalesce(v_base_n,0),1)::numeric/greatest(v_min,1))::int));
 v_alpha_look:=v_alpha/greatest(v_looks,1);
 v_z:=case when v_alpha_look<=0.001 then 3.291 when v_alpha_look<=0.0025 then 3.023 when v_alpha_look<=0.005 then 2.807 when v_alpha_look<=0.01 then 2.576 else 1.96 end;
 with stats as (select v.id,v.name,v.weight,count(distinct x.subject_key)::int n,count(distinct case when o.outcome='conversion' then o.subject_key end)::int k,coalesce(sum(case when o.outcome='revenue' then o.value else 0 end),0) revenue from public.crm_experiment_variants v left join public.crm_experiment_exposures x on x.variant_id=v.id left join public.crm_experiment_outcomes o on o.variant_id=v.id and o.subject_key=x.subject_key where v.experiment_id=p_experiment_id group by v.id,v.name,v.weight), ci as (select s.*,case when s.n=0 then 0 else s.k::numeric/s.n end rate,case when s.n=0 then 0 else greatest(0,(s.k::numeric/s.n + v_z*v_z/(2*s.n) - v_z*sqrt(((s.k::numeric/s.n)*(1-s.k::numeric/s.n)+v_z*v_z/(4*s.n))/s.n))/(1+v_z*v_z/s.n)) end wilson_low,case when s.n=0 then 0 else least(1,(s.k::numeric/s.n + v_z*v_z/(2*s.n) + v_z*sqrt(((s.k::numeric/s.n)*(1-s.k::numeric/s.n)+v_z*v_z/(4*s.n))/s.n))/(1+v_z*v_z/s.n)) end wilson_high from stats s), base as (select * from ci where id=v_base_id), judged as (select c.*,case when c.id=v_base_id then false else c.n>=v_min and c.rate >= (select rate from base)*(1-v_reg) and c.wilson_low > (select wilson_high from base) end eligible from ci c)
 select jsonb_build_object('experiment_id',p_experiment_id,'baseline_variant_id',v_base_id,'variants',coalesce((select jsonb_agg(jsonb_build_object('id',j.id,'name',j.name,'weight',j.weight,'exposures',j.n,'conversions',j.k,'conversion_rate',j.rate,'revenue',j.revenue,'is_baseline',j.id=v_base_id,'wilson_lower',j.wilson_low,'wilson_upper',j.wilson_high,'eligible_for_winner',j.eligible) order by j.name) from judged j),'[]'::jsonb),'guardrails',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'metric_name',g.metric_name,'metric_type',g.metric_type,'min_sample_size',g.min_sample_size,'max_regression',g.max_regression,'enabled',g.enabled) order by g.metric_name) from public.crm_experiment_guardrails g where g.experiment_id=p_experiment_id and g.enabled),'[]'::jsonb),'sequential',jsonb_build_object('method','bonferroni_repeated_look_conservative_v1','alpha',v_alpha,'max_looks',v_looks,'look',v_look,'alpha_per_look',v_alpha_look,'z_score',v_z,'minimum_sample_size',v_min,'max_regression',v_reg,'status',case when coalesce((select n from base),0)=0 then 'awaiting_baseline_data' else 'sequential_monitoring' end),'winner_eligible',exists(select 1 from judged where eligible),'eligible_variant_ids',coalesce((select jsonb_agg(id order by name) from judged where eligible),'[]'::jsonb),'generated_at',now()) into v;
 return v;
end $$;
revoke all on function public.crm_experiment_report(uuid) from public,anon; grant execute on function public.crm_experiment_report(uuid) to authenticated;